@import url('https://fonts.googleapis.com/css2?family=DM+Mono:wght@400;500&family=DM+Sans:wght@400;500;600;700;800&family=Oswald:wght@500;600;700&display=swap');
:root{--ink:#f4f2e9;--muted:#9aaba3;--dim:#688078;--green:#c9f36b;--green-dark:#16291f;--bg:#071b17;--panel:#10251f;--line:rgba(230,242,226,.11);--mono:'DM Mono',monospace;--head:'Oswald',sans-serif;--body:'DM Sans',sans-serif}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:var(--body);min-height:100vh;background-image:radial-gradient(ellipse at 74% -12%,rgba(81,123,76,.18),transparent 40%),linear-gradient(115deg,rgba(16,54,39,.2),transparent 46%)}button{font:inherit;color:inherit}.game-shell{width:min(1160px,calc(100% - 64px));margin:auto}.topbar{height:76px;border-bottom:1px solid var(--line);display:flex;align-items:center;justify-content:space-between}.brand{display:flex;align-items:center;gap:10px;color:var(--ink);text-decoration:none;font:700 14px var(--head);letter-spacing:1.6px}.brand-mark{width:32px;height:32px;display:grid;place-items:center;background:var(--green);color:#14231a;font:700 22px var(--head);transform:skew(-8deg)}.brand-sub{display:block;color:#80958a;font:500 8px var(--mono);letter-spacing:2px;margin-top:3px}.top-center,.stadium-head,.stadium-head>div{display:flex;align-items:center;gap:9px;color:#91a69b;font:10px var(--mono);letter-spacing:1.1px}.live-dot{height:7px;width:7px;background:var(--green);border-radius:50%;box-shadow:0 0 12px #c9f36b88;display:inline-block}.top-divider{color:#40584d}.icon-button{width:34px;height:34px;border:1px solid var(--line);border-radius:50%;background:transparent;color:var(--green);cursor:pointer}.intro-row{display:flex;align-items:flex-end;justify-content:space-between;padding:35px 0 25px}.eyebrow{font:10px var(--mono);letter-spacing:1.4px;color:#9bad9e;margin:0 0 8px}.eyebrow span{color:var(--green);padding:0 4px}h1{font:600 clamp(38px,5.2vw,58px)/.93 var(--head);letter-spacing:1px;margin:0}h1 em{font-style:normal;color:var(--green)}.intro-note{font-size:13px;line-height:1.55;color:#8da198;margin:0 0 3px;text-align:right}.mobile-break{display:none}.match-layout{display:grid;grid-template-columns:minmax(0,1fr) 276px;gap:20px}.main-column,.side-column{min-width:0}.scoreboard{min-height:95px;border:1px solid var(--line);background:linear-gradient(100deg,#142c22,#10241e);display:grid;grid-template-columns:1fr auto 1fr;align-items:center;padding:15px 20px;margin-bottom:14px;position:relative;overflow:hidden}.scoreboard:after{content:'';position:absolute;right:-20px;top:-44px;width:120px;height:120px;border:1px solid #c9f36b13;border-radius:50%;box-shadow:0 0 0 15px #c9f36b08,0 0 0 31px #c9f36b06}.score-team{display:flex;align-items:center;gap:10px}.team-badge{width:35px;height:35px;border-radius:50%;display:grid;place-items:center;background:#d9e3be;color:#243b24;font:600 19px var(--head);border:2px solid #ffffff50}.team-name{display:block;font:600 13px var(--head);letter-spacing:1px}.innings-tag{display:block;color:#8fa296;font:9px var(--mono);letter-spacing:.8px;margin-top:3px}.score-main{text-align:center}.score-numbers{font:600 43px/.9 var(--head);letter-spacing:.5px}.score-slash{color:#65786d;font-size:30px;padding:0 3px}.score-meta{color:#92a59a;font:9px var(--mono);letter-spacing:.6px;margin-top:7px}.meta-sep{color:var(--green);padding:0 3px}.target-block{text-align:right;z-index:1}.target-label,.target-block small{display:block;color:#92a59a;font:9px var(--mono);letter-spacing:1px}.target-block strong{display:block;color:var(--green);font:500 23px var(--head);margin:2px 0}.stadium-card{border:1px solid var(--line);background:#10241e;margin-bottom:14px}.stadium-head{height:35px;padding:0 13px;justify-content:space-between;border-bottom:1px solid var(--line);font-size:9px}.stadium-head .live-dot{height:6px;width:6px}.weather{color:#8e9d8e}.scene-wrap{height:220px;position:relative;overflow:hidden;background:#335a3a}.scene-wrap canvas{display:block;width:100%;height:100%}.scene-overlay{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;flex-direction:column;background:linear-gradient(0deg,rgba(2,18,14,.32),rgba(2,18,14,.03));text-align:center;pointer-events:none;transition:opacity .3s}.scene-overlay.hide{opacity:0}.scene-overlay strong{font:600 14px var(--head);letter-spacing:1.8px;text-shadow:0 2px 10px #000}.scene-overlay small{font-size:10px;color:#e3e9d7;margin-top:4px;text-shadow:0 1px 5px #000}.whistle{color:var(--green);font-size:20px;margin-bottom:6px}.ball-callout{position:absolute;left:50%;top:48%;transform:translate(-50%,-50%);font:600 26px var(--head);color:#efffd2;text-shadow:0 2px 9px #10231b;opacity:0;pointer-events:none}.ball-callout.show{animation:callout 1.2s ease-out}@keyframes callout{0%{opacity:0;transform:translate(-50%,-35%) scale(.8)}20%{opacity:1;transform:translate(-50%,-50%) scale(1.12)}70%{opacity:1}100%{opacity:0;transform:translate(-50%,-70%) scale(1)}}.stadium-foot{min-height:51px;display:flex;align-items:center;justify-content:space-between;padding:8px 13px;gap:12px;border-top:1px solid var(--line)}.foot-label{font:8px var(--mono);letter-spacing:1px;color:#82948a}.ball-track{display:flex;gap:4px;margin-top:5px;align-items:center}.ball-chip{height:17px;min-width:17px;border-radius:50%;border:1px solid #4a6558;color:#9cad9d;display:grid;place-items:center;font:8px var(--mono)}.ball-chip.run{background:#324d3b;border-color:#789267;color:#d9e6cd}.ball-chip.boundary{background:var(--green);color:#19251c;border-color:var(--green);font-weight:bold}.ball-chip.wicket{background:#ed735b;border-color:#ed735b;color:#fff}.ball-chip.current{border-color:var(--green);color:var(--green)}.commentary{font-size:10px;color:#a8b7aa;text-align:right;max-width:60%;line-height:1.35}.control-panel{border:1px solid var(--line);background:linear-gradient(110deg,#142b22,#10231d);padding:16px 18px 13px;margin-bottom:15px}.panel-heading{display:flex;align-items:center;justify-content:space-between;margin-bottom:13px}.panel-heading .eyebrow{margin-bottom:3px;color:var(--green);font-size:9px}.panel-heading h2{font:500 19px var(--head);margin:0;letter-spacing:.3px}.control-hint{font:9px var(--mono);color:#82958a}.setup-controls{display:grid;grid-template-columns:1fr 1fr auto;gap:8px}.side-card{position:relative;text-align:left;background:#0d211a;border:1px solid var(--line);padding:10px 12px 9px 37px;min-height:56px;cursor:pointer;transition:.15s}.side-card:hover,.side-card.selected{border-color:#9cce5c88;background:#192e20}.side-icon{position:absolute;left:11px;top:15px;color:var(--green);font-size:18px}.side-name{display:block;font:500 11px var(--head);letter-spacing:.7px}.side-desc{display:block;color:#879a8e;font-size:9px;margin-top:3px}.choose-dot{position:absolute;right:9px;top:9px;width:8px;height:8px;border:1px solid #748777;border-radius:50%}.selected .choose-dot{background:var(--green);border-color:var(--green);box-shadow:0 0 7px #c9f36b88}.primary-button{background:var(--green);color:#142116;border:0;padding:0 16px;min-height:44px;font:600 11px var(--head);letter-spacing:.7px;cursor:pointer;transition:background .15s,transform .15s;white-space:nowrap}.primary-button span{font:14px var(--body);margin-left:8px}.primary-button:hover{background:#dafb91;transform:translateY(-1px)}.bat-controls,.bowl-controls{display:grid;grid-template-columns:1.15fr .85fr auto;gap:9px;align-items:center}.control-group{min-width:0}.control-label{display:block;color:#82958a;font:8px var(--mono);letter-spacing:1px;margin:0 0 6px}.choice-row{display:flex;gap:5px}.choice{position:relative;background:#0e211a;border:1px solid var(--line);padding:7px 8px;min-height:39px;flex:1;text-align:left;font:500 10px var(--head);letter-spacing:.25px;cursor:pointer}.choice span{display:block;color:#8a9a8f;font:7px var(--mono);margin-top:3px;letter-spacing:.4px}.choice.active{border-color:#a9d867;background:#1a3021;color:#d4f790}.choice.active span{color:#b4d17f}.aim-row{display:flex;gap:5px}.aim{height:39px;flex:1;border:1px solid var(--line);background:#0e211a;color:#c1d1c3;font:17px var(--body);cursor:pointer}.aim small{display:block;font:7px var(--mono);color:#82958a;letter-spacing:.2px}.aim.active{border-color:#a9d867;background:#1a3021;color:var(--green)}.action-button{min-width:135px}.timing-note{grid-column:1/-1;text-align:center;color:#83988a;font:8px var(--mono);letter-spacing:.5px;margin-top:-3px}.between-controls,.result-controls{display:flex;align-items:center;justify-content:space-between;gap:10px}.between-controls p,.result-controls p{margin:0;color:#b1c0b4;font-size:12px}.hidden{display:none!important}.side-column{display:flex;flex-direction:column;gap:12px}.side-card-panel{border:1px solid var(--line);background:#10241e;padding:13px 14px}.side-panel-head{display:flex;justify-content:space-between;align-items:center;color:#9eafa2;font:9px var(--mono);letter-spacing:1px;padding-bottom:10px;border-bottom:1px solid var(--line)}.panel-icon{color:var(--green);font-size:15px}.player-row{display:flex;align-items:center;padding-top:10px;gap:9px}.player-avatar{height:28px;width:28px;border-radius:50%;display:grid;place-items:center;font:600 9px var(--mono);color:#26372a;background:#b9c9a1}.avatar-two{background:#809b71;color:#17281b}.player-info{flex:1}.player-info strong,.bowler-info strong{display:block;font:500 10px var(--head);letter-spacing:.5px}.player-info small,.bowler-info small{display:block;color:#84978b;font:7px var(--mono);margin-top:3px;letter-spacing:.3px}.player-score{font:500 16px var(--head)}.player-score span{color:#87978b;font:9px var(--mono);margin-left:3px}.bowler-info{display:flex;align-items:center;gap:10px;padding:12px 0}.bowler-avatar{height:30px;width:30px;border-radius:50%;display:grid;place-items:center;background:#bd765e;color:#fff;font:500 9px var(--mono)}.bowler-stats{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);padding-top:10px}.bowler-stats div{text-align:center;border-right:1px solid var(--line)}.bowler-stats div:last-child{border:0}.bowler-stats strong{display:block;font:500 15px var(--head)}.bowler-stats small{display:block;color:#83968b;font:7px var(--mono);letter-spacing:.5px;margin-top:3px}.match-panel{padding-bottom:10px}.detail-row{display:flex;justify-content:space-between;padding-top:10px;font:8px var(--mono);color:#82958a;letter-spacing:.4px}.detail-row strong{color:#c3d0c4;font-weight:400}.tip-card{display:flex;gap:9px;padding:12px;background:#1b3022;border:1px solid #8eaf5c42}.tip-star{color:var(--green);font-size:18px}.tip-card strong{font:500 9px var(--mono);letter-spacing:.8px;color:var(--green)}.tip-card p{font-size:9px;color:#b5c3b4;line-height:1.45;margin:4px 0 0}.side-column{padding-bottom:8px}footer{height:45px;border-top:1px solid var(--line);display:flex;align-items:center;justify-content:space-between;color:#71857a;font:8px var(--mono);letter-spacing:1px}footer b{color:var(--green);font-size:13px;margin-left:4px}.toast{position:fixed;left:50%;bottom:22px;transform:translate(-50%,20px);padding:10px 15px;background:#d0f477;color:#152219;font:500 11px var(--mono);opacity:0;transition:.2s;pointer-events:none;z-index:5}.toast.show{opacity:1;transform:translate(-50%,0)}
@media(max-width:850px){.game-shell{width:min(700px,calc(100% - 32px))}.match-layout{grid-template-columns:1fr}.side-column{display:grid;grid-template-columns:1fr 1fr}.match-panel,.tip-card{display:none}.scene-wrap{height:250px}.intro-row{padding-top:30px}.side-column{gap:10px}.control-panel{margin-bottom:0}.setup-controls{grid-template-columns:1fr 1fr}.setup-controls>.primary-button{grid-column:1/-1}.bat-controls,.bowl-controls{grid-template-columns:1fr 1fr}.bat-controls .action-button,.bowl-controls .action-button{grid-column:1/-1}.timing-note{grid-column:1/-1}}
@media(max-width:520px){.game-shell{width:calc(100% - 24px)}.topbar{height:58px}.top-center{font-size:8px;gap:6px}.brand{font-size:12px}.brand-mark{height:29px;width:29px}.intro-row{padding:24px 0 17px}.eyebrow{font-size:8px}h1{font-size:42px}.intro-note{font-size:10px}.mobile-break{display:block}.match-layout{gap:10px}.scoreboard{min-height:80px;padding:10px 11px;grid-template-columns:1fr auto .7fr;margin-bottom:10px}.team-badge{height:29px;width:29px}.team-name{font-size:11px}.innings-tag{font-size:7px}.score-numbers{font-size:36px}.score-meta{font-size:8px}.target-block strong{font-size:19px}.target-label,.target-block small{font-size:7px}.stadium-card{margin-bottom:10px}.stadium-head{height:31px;padding:0 9px;font-size:8px}.weather{font-size:7px}.scene-wrap{height:195px}.stadium-foot{padding:8px 9px;min-height:47px}.commentary{font-size:8px;max-width:52%}.foot-label{font-size:7px}.ball-chip{height:15px;min-width:15px;font-size:7px}.control-panel{padding:13px 11px 11px}.panel-heading h2{font-size:17px}.control-hint{font-size:7px}.setup-controls{gap:6px}.side-card{padding:9px 8px 8px 31px;min-height:59px}.side-icon{left:8px}.side-name{font-size:10px}.side-desc{font-size:8px}.setup-controls .primary-button{min-height:40px}.side-column{gap:8px}.side-card-panel{padding:10px}.side-panel-head{font-size:8px;padding-bottom:8px}.player-row{gap:6px;padding-top:9px}.player-avatar{width:24px;height:24px;font-size:8px}.player-info strong{font-size:9px}.player-score{font-size:14px}.bowl-info{padding:9px 0}.bowler-stats strong{font-size:13px}footer{height:36px;font-size:7px}.bat-controls,.bowl-controls{gap:7px}.choice{padding:6px 5px;min-height:37px;font-size:9px}.choice span{font-size:6px}.aim{height:37px}.action-button{min-width:0;padding:0 9px;font-size:10px}.action-button span{font-size:10px;margin-left:3px}.timing-note{font-size:7px}.between-controls p,.result-controls p{font-size:10px}}
@media(max-width:360px){.top-center{display:none}.scoreboard{grid-template-columns:1fr auto .55fr;padding:9px 7px}.score-numbers{font-size:31px}.scene-wrap{height:175px}.weather{letter-spacing:0}.side-card-panel{padding:8px}.player-info strong{font-size:8px}.control-hint{display:none}}

(() => {
  const $ = (id) => document.getElementById(id);
  const canvas = $('scene'), ctx = canvas.getContext('2d');
  const state = { phase: 'setup', side: 'bat', innings: 1, runs: 0, wickets: 0, balls: 0, target: null, batterIdx: 0, batters: [{name:'J. MORGAN',runs:0,balls:0},{name:'A. KHAN',runs:0,balls:0}], bowler:{name:'R. CHANDRA',runs:0,wickets:0}, overLog:[], shot:'ground', aim:'straight', line:'stumps', length:'good', delivery:null, pending:null, sound:true, matchStart:0 };
  const clamp=(n,a,b)=>Math.max(a,Math.min(b,n));
  const random=(a,b)=>a+Math.random()*(b-a);
  let W=800,H=250,dpr=1, toastTimer;
  function resize(){const r=canvas.getBoundingClientRect();dpr=Math.min(devicePixelRatio||1,2);W=r.width;H=r.height;canvas.width=Math.round(W*dpr);canvas.height=Math.round(H*dpr);ctx.setTransform(dpr,0,0,dpr,0,0)}
  new ResizeObserver(resize).observe(canvas); resize();
  const overlay=(show)=>$('scene-message').classList.toggle('hide',!show);
  function notify(message){const el=$('toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),1800)}
  function setText(id,value){$(id).textContent=value}
  function getOvers(balls){return `${Math.floor(balls/6)}.${balls%6}`}
  function update(){
    const battingName=state.innings===1?(state.side==='bat'?'ROYALS':'CITY XI'):(state.side==='bat'?'CITY XI':'ROYALS');
    setText('batting-team',battingName);$('home-badge').textContent;
    setText('innings-label',state.innings===1?'1ST INNINGS':'2ND INNINGS');setText('runs',state.runs);setText('wickets',state.wickets);setText('overs',getOvers(state.balls));
    setText('run-rate',`RR ${state.balls?(state.runs/(state.balls/6)).toFixed(2):'0.00'}`);
    setText('target',state.target===null?'—':state.target);setText('target-label',state.target===null?'TARGET':'TO WIN');
    const need=state.target===null?'10 OVERS':`${Math.max(0,state.target-state.runs)} OFF ${Math.max(0,60-state.balls)} BALLS`;
    setText('need-rate',need);setText('batter-one',state.batters[0].name);setText('batter-two',state.batters[1].name);
    setText('batter-one-status',state.batterIdx===0?'STRIKER':'NON-STRIKER');setText('batter-two-status',state.batterIdx===1?'STRIKER':'NON-STRIKER');
    setText('batter-one-score',`${state.batters[0].runs}(${state.batters[0].balls})`);setText('batter-two-score',`${state.batters[1].runs}(${state.batters[1].balls})`);
    setText('bowler-overs',getOvers(state.balls));setText('bowler-runs',state.bowler.runs);setText('bowler-wickets',state.bowler.wickets);
    $('ball-track').innerHTML='';const inOver=state.balls%6;
    for(let i=0;i<6;i++){const c=document.createElement('span');c.className='ball-chip';if(i<inOver){const o=state.overLog[state.overLog.length-inOver+i];c.textContent=o?.label??'·';c.classList.add(o?.type??'run')}else if(i===inOver&&state.balls<60)c.classList.add('current');$('ball-track').appendChild(c)}
    const chasing=state.innings===2&&state.target!==null;setText('tip-text',chasing?`Need ${Math.max(0,state.target-state.runs)} from ${Math.max(0,60-state.balls)} balls. Pick your moments.`:'Lofted shots can clear the rope—but mistime one and you could be walking.');
  }
  function showPhaseControls(){
    ['setup-controls','bat-controls','bowl-controls','between-controls','result-controls'].forEach(id=>$(id).classList.add('hidden'));
    if(state.phase==='setup')$('setup-controls').classList.remove('hidden');
    if(state.phase==='batting')$('bat-controls').classList.remove('hidden');
    if(state.phase==='bowling')$('bowl-controls').classList.remove('hidden');
    if(state.phase==='break')$('between-controls').classList.remove('hidden');
    if(state.phase==='complete')$('result-controls').classList.remove('hidden');
    if(state.phase==='batting'){setText('control-eyebrow','YOU ARE BATTING');setText('control-title','Read it. Time it. Send it.');setText('control-hint','SPACE / TAP TO SWING')}
    else if(state.phase==='bowling'){setText('control-eyebrow','YOU ARE BOWLING');setText('control-title','Set the field. Beat the bat.');setText('control-hint','SPACE / TAP TO BOWL')}
    else if(state.phase==='setup'){setText('control-eyebrow','CHOOSE YOUR SIDE');setText('control-title','How do you want to play?');setText('control-hint','10 overs · 2 innings')}
    else if(state.phase==='break'){setText('control-eyebrow','INNINGS BREAK');setText('control-title','The chase is on.');setText('control-hint','TARGET SET')}
    else {setText('control-eyebrow','FULL TIME');setText('control-title','That’s the game.');setText('control-hint','CITY LEAGUE · FINAL')}
  }
  document.querySelectorAll('.side-card[data-side]').forEach(b=>b.onclick=()=>{state.side=b.dataset.side;document.querySelectorAll('.side-card').forEach(x=>x.classList.toggle('selected',x===b))});
  function bindChoices(parent,key){document.querySelectorAll(`#${parent} [data-${key}]`).forEach(b=>b.onclick=()=>{state[key]=b.dataset[key];document.querySelectorAll(`#${parent} [data-${key}]`).forEach(x=>x.classList.toggle('active',x===b))})}
  bindChoices('shot-options','shot');bindChoices('aim-options','aim');bindChoices('line-options','line');bindChoices('length-options','length');
  $('start-match').onclick=()=>{state.innings=1;state.runs=0;state.wickets=0;state.balls=0;state.target=null;state.batterIdx=0;state.batters=[{name:'J. MORGAN',runs:0,balls:0},{name:'A. KHAN',runs:0,balls:0}];state.bowler={name:'R. CHANDRA',runs:0,wickets:0};state.overLog=[];state.phase=state.side==='bat'?'batting':'bowling';state.matchStart=Date.now();$('match-status').textContent='LIVE MATCH';overlay(true);setText('commentary',state.side==='bat'?'You’re opening the innings. Find your rhythm.':'The Royals are at the crease. Set your first trap.');showPhaseControls();update();$('home-badge').textContent=state.side==='bat'?'R':'C';};
  $('continue-match').onclick=()=>{state.innings=2;state.runs=0;state.wickets=0;state.balls=0;state.batterIdx=0;state.batters=[{name:'S. PATEL',runs:0,balls:0},{name:'D. REED',runs:0,balls:0}];state.bowler={name:'R. CHANDRA',runs:0,wickets:0};state.overLog=[];state.phase=state.side==='bat'?'bowling':'batting';setText('commentary',state.phase==='batting'?'The target is set. Time to chase.':'Defend your total. Make every ball count.');overlay(true);showPhaseControls();update()};
  $('new-match').onclick=()=>{state.phase='setup';state.innings=1;state.runs=0;state.wickets=0;state.balls=0;state.target=null;state.batters=[{name:'J. MORGAN',runs:0,balls:0},{name:'A. KHAN',runs:0,balls:0}];state.bowler={name:'R. CHANDRA',runs:0,wickets:0};state.overLog=[];setText('match-status','MATCH DAY');setText('commentary','The crowd is settling in. Time to make some noise.');overlay(true);showPhaseControls();update()};
  function startBatBall(){if(state.phase!=='batting')return;if(state.delivery)return;state.delivery={start:performance.now(),swung:false,kind:'bat'};overlay(false);$('play-ball').innerHTML='SWING NOW <span>SPACE ↗</span>';setText('commentary','Watch it closely…');$('play-ball').classList.add('ready-swing')}
  function swing(){if(state.phase!=='batting')return;if(!state.delivery){startBatBall();return}if(state.delivery.swung)return;state.delivery.swung=true;const elapsed=performance.now()-state.delivery.start;const timing=clamp(1-Math.abs(elapsed-1320)/1150,0,1);const timingName=timing>.78?'PERFECT TIMING':timing>.48?'GOOD TIMING':'LATE / EARLY';const shot=state.shot;let outcomes;
    if(shot==='defend') outcomes=[['dot',.55],['1',.33],['2',.08],['W',.04]];
    else if(shot==='loft') outcomes=[['0',.10],['1',.13],['2',.13],['3',.05],['4',.16],['6',.18],['W',.25]];
    else outcomes=[['0',.18],['1',.34],['2',.17],['3',.04],['4',.18],['6',.03],['W',.06]];
    let roll=Math.random();let selected=outcomes.find(x=>(roll-=x[1])<=0)?.[0]||'1';
